function Purse() {}
Purse.prototype.coins = [];
Purse.prototype.total = 0;
Purse.prototype.add = function (coin) {
  this.coins.push(coin);
  this.total += coin;
};

const a = new Purse();
const b = new Purse();
a.add(2);
b.add(5);

Purse.prototype = { total: 100 };
const c = new Purse();

console.log(a.total, b.total, c.total);
console.log(a.coins.length, c.coins);
console.log(a.constructor === Purse, c.constructor === Object);
